        .innerJoin(workspaces, eq(workspaces.id, aiRequests.workspaceId))
        .where(where)
        .orderBy(desc(aiRequests.createdAt))
        .limit(limit)
        .offset((page - 1) * limit),
      this.database.db
        .select({ total: sql<number>`count(*)::int` })
        .from(aiRequests)
        .innerJoin(users, eq(users.id, aiRequests.requestedByUserId))
        .innerJoin(workspaces, eq(workspaces.id, aiRequests.workspaceId))
        .where(where),
