  succeeded: "Correcta",
  failed: "Fallida",
  cancelled: "Cancelada",
}

const statusVariants: Record<
  RequestLog["status"],
  "info" | "warning" | "success" | "destructive" | "neutral"
> = {
  queued: "info",
  processing: "warning",
  succeeded: "success",
  failed: "destructive",
