            </TableBody>
          </Table>
          <TablePagination
            canGoNext={safePage < pageCount}
            canGoPrevious={safePage > 1}
            itemLabel="generaciones"
            onNextPage={() =>
              setPage((current) => Math.min(current + 1, pageCount))
            }
            onPreviousPage={() => setPage((current) => Math.max(current - 1, 1))}
            rangeEnd={rangeEnd}
            rangeStart={rangeStart}
            total={data.total}
          />
        </CardContent>
      </Card>
