const pageSize = 25

function CollectionSheet({
  fields,
  formDescription,
  onOpenChange,
  onSubmit,
  open,
  pending,
  title,
  values: initialValues,
}: {
  fields: readonly CollectionField[]
  formDescription: string
  onOpenChange: (open: boolean) => void
  onSubmit: (values: CollectionValues) => Promise<boolean>
  open: boolean
  pending: boolean
  title: string
  values: CollectionValues
}) {
  const [values, setValues] = useState<CollectionValues>(initialValues)

  useEffect(() => {
    if (open) setValues(initialValues)
  }, [initialValues, open])

  function update(name: string, value: unknown) {
    setValues((current) => ({ ...current, [name]: value }))
  }

  const canSubmit = fields
    .filter((field) => "required" in field && field.required)
    .every((field) => String(values[field.name] ?? "").trim().length > 0)

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!canSubmit) {
      toast.error("Completa todos los campos obligatorios.")
      return
    }
    const saved = await onSubmit(values)
    if (saved) onOpenChange(false)
  }

  return (
    <Sheet onOpenChange={onOpenChange} open={open}>
      <SheetContent className="w-full gap-0 p-0 sm:max-w-lg" side="right">
        <SheetHeader className="border-b">
          <SheetTitle>{title}</SheetTitle>
          <SheetDescription>{formDescription}</SheetDescription>
        </SheetHeader>
        <form
          aria-busy={pending}
          className="flex min-h-0 flex-1 flex-col"
          noValidate
          onSubmit={(event) => void submit(event)}
        >
          <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto p-4">
            <FieldGroup>
              {fields.map((field) => {
                const controlId = `collection-${field.name}`
                const required = "required" in field && field.required

                if (field.kind === "switch") {
                  return (
                    <Field key={field.name} orientation="horizontal">
                      <Switch
                        checked={Boolean(values[field.name])}
                        disabled={pending}
                        id={controlId}
                        onCheckedChange={(checked) =>
                          update(field.name, checked)
                        }
                      />
                      <FieldLabel htmlFor={controlId}>
                        <FieldContent>
                          <FieldTitle>{field.label}</FieldTitle>
                          {field.description ? (
                            <FieldDescription>
                              {field.description}
                            </FieldDescription>
                          ) : null}
                        </FieldContent>
                      </FieldLabel>
                    </Field>
                  )
                }

                if (field.kind === "checkboxes") {
                  const selected = Array.isArray(values[field.name])
                    ? (values[field.name] as string[])
                    : []
                  return (
                    <FieldSet key={field.name}>
                      <FieldLabel asChild>
                        <legend>{field.label}</legend>
                      </FieldLabel>
                      {field.options.length ? (
                        <FieldGroup className="gap-3" data-slot="checkbox-group">
                          {field.options.map((option) => {
                            const optionId = `${controlId}-${option.value}`
                            return (
                              <Field key={option.value} orientation="horizontal">
                                <Checkbox
                                  checked={selected.includes(option.value)}
                                  disabled={pending}
                                  id={optionId}
                                  onCheckedChange={(checked) =>
                                    update(
                                      field.name,
                                      checked === true
                                        ? [...selected, option.value]
                                        : selected.filter(
                                            (value) => value !== option.value
                                          )
                                    )
                                  }
                                />
                                <FieldLabel htmlFor={optionId}>
                                  <FieldContent>
                                    <FieldTitle>{option.label}</FieldTitle>
                                  </FieldContent>
                                </FieldLabel>
                              </Field>
                            )
                          })}
                        </FieldGroup>
                      ) : (
                        <FieldDescription>
                          No hay opciones disponibles todavía.
                        </FieldDescription>
                      )}
                    </FieldSet>
                  )
                }

                return (
                  <Field key={field.name}>
                    <FieldLabel htmlFor={controlId}>
                      {field.label}
                      {required ? (
                        <>
                          {" "}
                          <span aria-hidden="true" className="text-destructive">
                            *
                          </span>
                          <span className="sr-only"> obligatorio</span>
                        </>
                      ) : null}
                    </FieldLabel>
                    {field.kind === "select" ? (
                      <Select
                        disabled={pending}
                        onValueChange={(value) => update(field.name, value)}
                        value={String(values[field.name] ?? "")}
                      >
                        <SelectTrigger
                          aria-required={required ? "true" : undefined}
                          className="w-full"
                          id={controlId}
                        >
                          <SelectValue placeholder="Selecciona una opción" />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectGroup>
                            {field.options.map((option) => (
                              <SelectItem key={option.value} value={option.value}>
                                {option.label}
                              </SelectItem>
                            ))}
                          </SelectGroup>
                        </SelectContent>
                      </Select>
                    ) : field.kind === "textarea" ? (
                      <Textarea
                        aria-required={required ? "true" : undefined}
                        disabled={pending}
                        id={controlId}
                        onChange={(event) =>
                          update(field.name, event.target.value)
                        }
                        placeholder={field.placeholder}
                        rows={5}
                        value={String(values[field.name] ?? "")}
                      />
                    ) : (
                      <Input
                        aria-required={required ? "true" : undefined}
                        disabled={pending}
                        id={controlId}
                        onChange={(event) =>
                          update(field.name, event.target.value)
                        }
                        placeholder={field.placeholder}
                        type={field.kind === "number" ? "number" : "text"}
                        value={String(values[field.name] ?? "")}
                      />
                    )}
                    {field.description ? (
                      <FieldDescription>{field.description}</FieldDescription>
                    ) : null}
                  </Field>
                )
              })}
            </FieldGroup>
          </div>
          <SheetFooter className="flex-row justify-end border-t">
            <Button
              disabled={pending}
              onClick={() => onOpenChange(false)}
              type="button"
              variant="brand-secondary"
            >
              <X data-icon="inline-start" /> Cancelar
            </Button>
            <Button disabled={!canSubmit || pending} type="submit">
              {pending ? (
                <Spinner data-icon="inline-start" />
              ) : (
                <Plus data-icon="inline-start" />
              )}
              Guardar
            </Button>
          </SheetFooter>
        </form>
      </SheetContent>
    </Sheet>
  )
}

export function AdminCollectionPage<TRow, TResponse>({
  config,
}: {
  config: AdminCollectionConfig<TRow, TResponse>
}) {
  const router = useRouter()
  const [response, setResponse] = useState<TResponse | null>(null)
  const [query, setQuery] = useState("")
  const [status, setStatus] = useState("all")
  const [page, setPage] = useState(1)
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState(false)
  const [forbidden, setForbidden] = useState(false)
  const [pending, setPending] = useState(false)
  const [isSheetOpen, setIsSheetOpen] = useState(false)
  const [editing, setEditing] = useState<TRow | null>(null)
  const [toDelete, setToDelete] = useState<TRow | null>(null)

  const handleError = useCallback(
    (error: unknown) => {
      if (error instanceof ApiError && error.code === "AUTH_SESSION_EXPIRED") {
        router.replace("/login")
        return true
      }
      if (error instanceof ApiError && error.status === 403) {
        setForbidden(true)
        return true
      }
      return false
    },
    [router]
  )

  const load = useCallback(async () => {
    setIsLoading(true)
    setLoadError(false)
    try {
      setResponse(
        await config.load({
          limit: pageSize,
          page,
          ...(query.trim() ? { q: query.trim() } : {}),
          ...(config.filter && status !== "all" ? { status } : {}),
        })
      )
      setForbidden(false)
    } catch (error) {
      if (handleError(error)) return
      console.error(`${config.title} request failed`, error)
      setLoadError(true)
    } finally {
      setIsLoading(false)
    }
  }, [config, handleError, page, query, status])

  useEffect(() => {
    const timer = setTimeout(() => void load(), query ? 300 : 0)
    return () => clearTimeout(timer)
  }, [load, query])

  async function save(values: CollectionValues) {
    setPending(true)
    try {
      await config.save(editing ? config.rowId(editing) : null, values)
      await load()
      toast.success(editing ? "Cambios guardados." : "Registro creado.")
      return true
    } catch (error) {
      if (handleError(error)) return false
      console.error(`${config.title} save failed`, error)
      toast.error("No pudimos guardar. Revisa los datos e inténtalo de nuevo.")
      return false
    } finally {
      setPending(false)
    }
  }

  async function remove(row: TRow) {
    setPending(true)
    try {
      await config.remove(row)
      setToDelete(null)
      await load()
      toast.success("Registro eliminado.")
    } catch (error) {
      if (handleError(error)) return
      console.error(`${config.title} deletion failed`, error)
      toast.error("No pudimos eliminar el registro. Inténtalo de nuevo.")
    } finally {
      setPending(false)
    }
  }

  if (forbidden) {
    return (
      <Card variant="subtle">
        <CardContent>
          <EmptyState
            description="Solicita a un administrador el permiso necesario para gestionar este contenido."
            icon={ShieldCheck}
            title={`${config.title} no disponible`}
          />
        </CardContent>
      </Card>
    )
  }

  if (isLoading && !response && !loadError) {
    return <PageLoading aria-label={`Cargando ${config.itemLabel}`} />
  }

  if (loadError || !response) {
    return (
      <Card variant="subtle">
        <CardContent>
          <EmptyState
            action={
              <RetryButton
                onClick={() => void load()}
                variant="brand-secondary"
              />
            }
            description={`No pudimos cargar ${config.itemLabel}.`}
            icon={CircleAlert}
            title={`${config.title} no disponible`}
          />
        </CardContent>
      </Card>
    )
  }

  const rows = config.rows(response)
  const total = config.total(response)
  const pageCount = Math.max(1, Math.ceil(total / pageSize))
  const safePage = Math.min(page, pageCount)
  const rangeStart = total ? (safePage - 1) * pageSize + 1 : 0
  const rangeEnd = total ? rangeStart + rows.length - 1 : 0
  const hasFilters = Boolean(query || status !== "all")

  function clearFilters() {
    setQuery("")
    setStatus("all")
    setPage(1)
  }

  function openCreate() {
    setEditing(null)
    setIsSheetOpen(true)
  }

  return (
    <>
      <div className="flex flex-col gap-4">
        <CollectionHeader
          description={config.description}
          title={config.title}
        />
        <Card variant="subtle">
          <DataTableHeader
            action={
              <Button
                className="hidden sm:inline-flex"
                onClick={openCreate}
                size="sm"
                type="button"
              >
                <Plus data-icon="inline-start" /> {config.createLabel}
              </Button>
            }
            search={{
              ariaLabel: `Buscar ${config.itemLabel}`,
              onChange: (value) => {
                setQuery(value)
                setPage(1)
              },
              placeholder: config.searchPlaceholder,
              value: query,
            }}
          />
          <CardContent className="flex flex-col gap-4 px-0">
            {config.filter ? (
              <DataTableToolbar
                actions={
                  hasFilters ? (
                    <Button
                      onClick={clearFilters}
                      size="sm"
                      type="button"
                      variant="outline"
                    >
                      <X /> Limpiar
                    </Button>
                  ) : undefined
                }
              >
                <DataTableFilter
                  ariaLabel={`Filtrar por ${config.filter.label.toLowerCase()}`}
                  label={config.filter.label}
                  onValueChange={(value) => {
                    setStatus(value)
                    setPage(1)
                  }}
                  options={config.filter.options}
                  value={status}
                />
              </DataTableToolbar>
            ) : null}
            <Table>
              <TableHeader>
                <TableRow>
                  {config.columns.map((column) => (
                    <TableHead
                      className={
                        column.hideBelow === "lg"
                          ? "hidden lg:table-cell"
                          : column.hideBelow === "md"
                            ? "hidden md:table-cell"
                            : undefined
                      }
                      key={column.key}
                    >
                      {column.label}
                    </TableHead>
                  ))}
                  <TableHead className="text-right">Acciones</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {rows.length ? (
                  rows.map((row) => (
                    <TableRow key={config.rowId(row)}>
                      {config.columns.map((column) => (
                        <TableCell
                          className={
                            column.hideBelow === "lg"
                              ? "hidden lg:table-cell"
                              : column.hideBelow === "md"
                                ? "hidden md:table-cell"
                                : undefined
                          }
                          key={column.key}
                        >
                          {column.render(row)}
                        </TableCell>
                      ))}
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button
                              aria-label={`Abrir acciones para ${config.rowName(row)}`}
                              className="size-8 rounded-md text-muted-foreground hover:bg-muted/50"
                              size="icon-sm"
                              variant="brand-secondary"
                            >
                              <MoreHorizontal className="size-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" size="compact">
                            <DropdownMenuItem
                              onSelect={() => {
                                setEditing(row)
                                setIsSheetOpen(true)
                              }}
                              size="compact"
                            >
                              <Pencil />
                              Editar
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              onSelect={() => setToDelete(row)}
                              size="compact"
                              variant="destructive"
                            >
                              <Trash2 />
                              Eliminar
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableEmptyRow
                    action={
                      hasFilters ? (
                        <Button onClick={clearFilters} variant="outline">
                          Restablecer filtros
                        </Button>
                      ) : null
                    }
                    colSpan={config.columns.length + 1}
                    description={
                      hasFilters
                        ? "Prueba con otro término o restablece los filtros."
                        : config.emptyDescription
                    }
                    icon={config.emptyIcon}
                    title={hasFilters ? "No hay coincidencias" : config.emptyTitle}
                  />
                )}
              </TableBody>
            </Table>
            <TablePagination
              canGoNext={safePage < pageCount}
              canGoPrevious={safePage > 1}
              itemLabel={config.itemLabel}
              onNextPage={() =>
                setPage((current) => Math.min(current + 1, pageCount))
              }
              onPreviousPage={() =>
                setPage((current) => Math.max(current - 1, 1))
              }
              rangeEnd={rangeEnd}
              rangeStart={rangeStart}
              total={total}
            />
          </CardContent>
        </Card>
        <FloatingActionButton label={config.createLabel} onClick={openCreate} />
      </div>

      <CollectionSheet
        fields={config.fields}
        formDescription={config.formDescription}
        onOpenChange={setIsSheetOpen}
        onSubmit={save}
        open={isSheetOpen}
        pending={pending}
        title={editing ? `Editar ${config.rowName(editing)}` : config.createLabel}
        values={config.toValues(editing, response)}
      />

      <AlertDialog
        onOpenChange={(open) => !open && setToDelete(null)}
        open={Boolean(toDelete)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              ¿Eliminar “{toDelete ? config.rowName(toDelete) : ""}”?
            </AlertDialogTitle>
            <AlertDialogDescription>
              Esta acción no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={pending}>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              disabled={pending}
              onClick={(event) => {
                event.preventDefault()
                if (toDelete) void remove(toDelete)
              }}
              variant="destructive"
            >
              {pending ? <Spinner data-icon="inline-start" /> : null}
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
