import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@workspace/ui/components/table"
import { TableEmptyRow } from "@workspace/ui/components/table-empty-row"
import { Textarea } from "@workspace/ui/components/textarea"
import { toast } from "@workspace/ui/components/toast"

const emptyPage: AdminStaticPage = {
  slug: "",
  title: "",
  content: "",
  isPublished: false,
}

function slugify(value: string) {
  return value
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80)
}

export function StaticPagesSettingsPage() {
  const router = useRouter()
  const [pages, setPages] = useState<AdminStaticPage[] | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState(false)
  const [forbidden, setForbidden] = useState(false)
  const [pending, setPending] = useState(false)
  const [isSheetOpen, setIsSheetOpen] = useState(false)
  const [draft, setDraft] = useState<AdminStaticPage>(emptyPage)
  const [editingSlug, setEditingSlug] = useState<string | null>(null)
  const [toDelete, setToDelete] = useState<AdminStaticPage | null>(null)

  const handleError = useCallback(
    (error: unknown) => {
      if (error instanceof ApiError && error.code === "AUTH_SESSION_EXPIRED") {
        router.replace("/login")
        return true
      }
      if (error instanceof ApiError && error.status === 403) {
        setForbidden(true)
        return true
      }
      return false
    },
    [router]
  )

  const load = useCallback(async () => {
    setIsLoading(true)
    setLoadError(false)
    try {
      const response = await adminSettingsApi.staticPages()
      setPages(response.pages)
      setForbidden(false)
    } catch (error) {
      if (handleError(error)) return
      console.error("Static pages request failed", error)
      setLoadError(true)
    } finally {
      setIsLoading(false)
    }
  }, [handleError])

  useEffect(() => {
    void load()
  }, [load])

  async function persist(next: AdminStaticPage[]) {
    setPending(true)
    try {
      const response = await adminSettingsApi.saveStaticPages({ pages: next })
      setPages(response.pages)
      return true
    } catch (error) {
      if (handleError(error)) return false
      console.error("Static pages save failed", error)
      toast.error("No pudimos guardar las páginas. Inténtalo de nuevo.")
      return false
    } finally {
      setPending(false)
    }
  }

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!pages) return
    const slug = draft.slug.trim() || slugify(draft.title)
    if (!draft.title.trim() || !slug) {
      toast.error("La página necesita título.")
      return
    }
    const entry = { ...draft, slug }
    const next = editingSlug
      ? pages.map((page) => (page.slug === editingSlug ? entry : page))
      : [...pages, entry]
    if (!editingSlug && pages.some((page) => page.slug === slug)) {
      toast.error("Ya existe una página con esa dirección.")
      return
    }
    if (await persist(next)) {
      setIsSheetOpen(false)
      toast.success(editingSlug ? "Página actualizada." : "Página creada.")
    }
  }

  async function remove(page: AdminStaticPage) {
    if (!pages) return
    if (await persist(pages.filter((item) => item.slug !== page.slug))) {
      setToDelete(null)
      toast.success("Página eliminada.")
    }
  }

  if (forbidden) {
    return (
      <Card variant="subtle">
        <CardContent>
          <EmptyState
            description="Solicita a un administrador el permiso necesario para editar las páginas."
            icon={ShieldCheck}
            title="Páginas no disponibles"
          />
        </CardContent>
      </Card>
    )
  }

  if (isLoading && !pages) {
    return <PageLoading aria-label="Cargando páginas estáticas" />
  }

  if (loadError || !pages) {
    return (
      <Card variant="subtle">
        <CardContent>
          <EmptyState
            action={
              <RetryButton
                onClick={() => void load()}
                variant="brand-secondary"
              />
            }
            description="No pudimos cargar las páginas estáticas."
            icon={CircleAlert}
            title="Páginas no disponibles"
          />
        </CardContent>
      </Card>
    )
  }

  function openCreate() {
    setDraft(emptyPage)
    setEditingSlug(null)
    setIsSheetOpen(true)
  }

  return (
    <>
      <div className="flex flex-col gap-4">
        <CollectionHeader
          description="Contenido legal e informativo que se publica fuera del Portal."
          title="Páginas estáticas"
        />
        <Card variant="subtle">
          <DataTableHeader
            action={
              <Button
                className="hidden sm:inline-flex"
                onClick={openCreate}
                size="sm"
                type="button"
              >
                <Plus data-icon="inline-start" /> Nueva página
              </Button>
            }
          />
          <CardContent className="px-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Página</TableHead>
                  <TableHead>Estado</TableHead>
                  <TableHead className="text-right">Acciones</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {pages.length ? (
                  pages.map((page) => (
                    <TableRow key={page.slug}>
                      <TableCell>
                        <div className="flex min-w-40 flex-col">
                          <span className="font-medium">{page.title}</span>
                          <span className="text-sm text-muted-foreground">
                            /{page.slug}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant={page.isPublished ? "success" : "neutral"}
                        >
                          {page.isPublished ? "Publicada" : "Borrador"}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button
                              aria-label={`Abrir acciones para ${page.title}`}
                              className="size-8 rounded-md text-muted-foreground hover:bg-muted/50"
                              size="icon-sm"
                              variant="brand-secondary"
                            >
                              <MoreHorizontal className="size-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end" size="compact">
                            <DropdownMenuItem
                              onSelect={() => {
                                setDraft(page)
                                setEditingSlug(page.slug)
                                setIsSheetOpen(true)
                              }}
                              size="compact"
                            >
                              <Pencil />
                              Editar
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              onSelect={() => setToDelete(page)}
                              size="compact"
                              variant="destructive"
                            >
                              <Trash2 />
                              Eliminar
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableEmptyRow
                    colSpan={3}
                    description="Crea páginas como términos de servicio o privacidad."
                    icon={FileText}
                    title="No hay páginas"
                  />
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
        <FloatingActionButton label="Nueva página" onClick={openCreate} />
      </div>

      <Sheet onOpenChange={setIsSheetOpen} open={isSheetOpen}>
        <SheetContent className="w-full gap-0 p-0 sm:max-w-2xl" side="right">
          <SheetHeader className="border-b">
            <SheetTitle>
              {editingSlug ? "Editar página" : "Nueva página"}
            </SheetTitle>
            <SheetDescription>
              La dirección se genera desde el título si la dejas vacía.
            </SheetDescription>
          </SheetHeader>
          <form
            aria-busy={pending}
            className="flex min-h-0 flex-1 flex-col"
            noValidate
            onSubmit={(event) => void submit(event)}
          >
            <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto p-4">
              <FieldGroup>
                <Field>
                  <FieldLabel htmlFor="page-title">
                    Título{" "}
                    <span aria-hidden="true" className="text-destructive">
                      *
                    </span>
                    <span className="sr-only"> obligatorio</span>
                  </FieldLabel>
                  <Input
                    aria-required="true"
                    disabled={pending}
                    id="page-title"
                    onChange={(event) =>
                      setDraft({ ...draft, title: event.target.value })
                    }
                    value={draft.title}
                  />
                </Field>
                <Field>
                  <FieldLabel htmlFor="page-slug">Dirección</FieldLabel>
                  <Input
                    disabled={pending}
                    id="page-slug"
                    onChange={(event) =>
                      setDraft({ ...draft, slug: event.target.value })
                    }
                    placeholder="terminos-de-servicio"
                    value={draft.slug}
                  />
                  <FieldDescription>
                    Solo minúsculas, números y guiones.
                  </FieldDescription>
                </Field>
                <Field>
                  <FieldLabel htmlFor="page-content">Contenido</FieldLabel>
                  <Textarea
                    disabled={pending}
                    id="page-content"
                    onChange={(event) =>
                      setDraft({ ...draft, content: event.target.value })
                    }
                    rows={12}
                    value={draft.content}
                  />
                </Field>
                <Field orientation="horizontal">
                  <Switch
                    checked={draft.isPublished}
                    disabled={pending}
                    id="page-published"
                    onCheckedChange={(checked) =>
                      setDraft({ ...draft, isPublished: checked })
                    }
                  />
                  <FieldLabel htmlFor="page-published">
                    <FieldContent>
                      <FieldTitle>Publicada</FieldTitle>
                      <FieldDescription>
                        Solo las publicadas son visibles fuera del Portal.
                      </FieldDescription>
                    </FieldContent>
                  </FieldLabel>
                </Field>
              </FieldGroup>
            </div>
            <SheetFooter className="flex-row justify-end border-t">
              <Button
                disabled={pending}
                onClick={() => setIsSheetOpen(false)}
                type="button"
                variant="brand-secondary"
              >
                <X data-icon="inline-start" /> Cancelar
              </Button>
              <Button disabled={pending || !draft.title.trim()} type="submit">
                {pending ? (
                  <Spinner data-icon="inline-start" />
                ) : (
                  <Plus data-icon="inline-start" />
                )}
                Guardar página
              </Button>
            </SheetFooter>
          </form>
        </SheetContent>
      </Sheet>

      <AlertDialog
        onOpenChange={(open) => !open && setToDelete(null)}
        open={Boolean(toDelete)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              ¿Eliminar “{toDelete?.title}”?
            </AlertDialogTitle>
            <AlertDialogDescription>
              La página dejará de estar disponible en su dirección pública.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={pending}>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              disabled={pending}
              onClick={(event) => {
                event.preventDefault()
                if (toDelete) void remove(toDelete)
              }}
              variant="destructive"
            >
              {pending ? <Spinner data-icon="inline-start" /> : null}
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
