"use client"

import { useCallback, useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import {
  CircleAlert,
  Clock,
  Database,
  ShieldCheck,
  Trash2,
} from "lucide-react"

import { ApiError, adminSettingsApi } from "@workspace/api-client"
import type { AdminCacheState, AdminScheduledJobs } from "@workspace/contracts"
import { Badge } from "@workspace/ui/components/badge"
import { Button } from "@workspace/ui/components/button"
import { Card, CardContent } from "@workspace/ui/components/card"
import { CardGrid } from "@workspace/ui/components/card-grid"
import { CollectionHeader } from "@workspace/ui/components/collection-header"
import { EmptyState } from "@workspace/ui/components/empty-state"
import { MetricCard } from "@workspace/ui/components/metric-card"
import { PageLoading } from "@workspace/ui/components/page-loading"
import { RetryButton } from "@workspace/ui/components/retry-button"
import { Spinner } from "@workspace/ui/components/spinner"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@workspace/ui/components/table"
import { TableEmptyRow } from "@workspace/ui/components/table-empty-row"
import { toast } from "@workspace/ui/components/toast"

function formatDateTime(value: string | null) {
  if (!value) return "Nunca"
  return new Intl.DateTimeFormat("es-EC", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(value))
}

function useAdminResource<T>(load: () => Promise<T>, label: string) {
  const router = useRouter()
  const [data, setData] = useState<T | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState(false)
  const [forbidden, setForbidden] = useState(false)

  const refresh = useCallback(async () => {
    setIsLoading(true)
    setLoadError(false)
    try {
      setData(await load())
      setForbidden(false)
    } catch (error) {
      if (error instanceof ApiError && error.code === "AUTH_SESSION_EXPIRED") {
        router.replace("/login")
        return
      }
      if (error instanceof ApiError && error.status === 403) {
        setForbidden(true)
        return
      }
      console.error(`${label} request failed`, error)
      setLoadError(true)
    } finally {
      setIsLoading(false)
    }
  }, [label, load, router])

  useEffect(() => {
    void refresh()
  }, [refresh])

  return { data, forbidden, isLoading, loadError, refresh, setData }
}

function StateGuard({
  children,
  forbidden,
  isLoading,
  loadError,
  onRetry,
  ready,
  title,
}: {
  children: React.ReactNode
  forbidden: boolean
  isLoading: boolean
  loadError: boolean
  onRetry: () => void
  ready: boolean
  title: string
}) {
  if (forbidden) {
    return (
      <Card variant="subtle">
        <CardContent>
          <EmptyState
            description="Solicita a un administrador el permiso necesario para ver esta información."
            icon={ShieldCheck}
            title={`${title} no disponible`}
          />
        </CardContent>
      </Card>
    )
  }
  if (isLoading && !ready) {
    return <PageLoading aria-label={`Cargando ${title.toLowerCase()}`} />
  }
  if (loadError || !ready) {
    return (
      <Card variant="subtle">
        <CardContent>
          <EmptyState
            action={<RetryButton onClick={onRetry} variant="brand-secondary" />}
            description="No pudimos consultar el estado de la infraestructura."
            icon={CircleAlert}
            title={`${title} no disponible`}
          />
        </CardContent>
      </Card>
    )
  }
  return <>{children}</>
}

export function CacheSettingsPage() {
  const { data, forbidden, isLoading, loadError, refresh, setData } =
    useAdminResource<AdminCacheState>(
      () => adminSettingsApi.cache(),
      "Caché"
    )
  const [pending, setPending] = useState(false)

  async function purge() {
    setPending(true)
    try {
      const result = await adminSettingsApi.purgeCache()
      toast.success(
        result.removed
          ? `Se vaciaron ${result.removed} claves de caché.`
          : "No había claves de caché que vaciar."
      )
      setData(await adminSettingsApi.cache())
    } catch (error) {
      console.error("Cache purge failed", error)
      toast.error("No pudimos vaciar la caché. Inténtalo de nuevo.")
    } finally {
      setPending(false)
    }
  }

  return (
    <StateGuard
      forbidden={forbidden}
      isLoading={isLoading}
      loadError={loadError}
      onRetry={() => void refresh()}
      ready={Boolean(data)}
      title="Caché"
    >
      <div className="flex flex-col gap-4">
        <CollectionHeader
          description="Estado de Redis y vaciado de la caché de aplicación."
          title="Caché"
        />
        <CardGrid layout="md-3">
          <MetricCard
            description="Claves almacenadas ahora"
            icon={Database}
            label="Claves"
            value={data?.keys ?? 0}
          />
          <MetricCard
            description="Memoria usada por Redis"
            icon={Database}
            label="Memoria"
            value={data?.memoryUsed ?? "—"}
          />
          <MetricCard
