import pathlib, re

def strip_icon(block: str) -> str:
    out = []
    i = 0
    while i < len(block):
        m = re.compile(r"[ \t]*icon=\{").search(block, i)
        if not m:
            out.append(block[i:])
            break
        out.append(block[i:m.start()])
        j = m.end()
        depth = 1
        while j < len(block) and depth:
            if block[j] == "{":
                depth += 1
            elif block[j] == "}":
                depth -= 1
            j += 1
        while j < len(block) and block[j] in " \t":
            j += 1
        if j < len(block) and block[j] == "\n":
            j += 1
        i = j
    return "".join(out)

changed = []
for path in pathlib.Path("apps/web/features").rglob("*.tsx"):
    text = path.read_text()
    if "TableEmptyRow" not in text:
        continue
    new = text
    for match in re.finditer(r"<TableEmptyRow\b.*?/>", text, re.S):
        block = match.group(0)
        if not re.search(r"\bicon=\{", block):
            continue
        new = new.replace(block, strip_icon(block))
    if new != text:
        path.write_text(new)
        changed.append(path.as_posix())
print("\n".join(changed))
