      },
      {
        primary: "The Konery",
        secondary: "thekonery.com",
        href: "https://www.thekonery.com/",
      },
    ],
  },
  Coding: {
    active: "Running tools",
    done: "Ran 3 tools",
    rows: [
      { primary: "Read", secondary: "flavors.ts", mono: true },
      {
        primary: "Edit",
        secondary: "ChurnSchedule.tsx",
        mono: true,
        add: 74,
        del: 41,
      },
      { primary: "Run", secondary: "npm run freeze", mono: true },
    ],
  },
};

function Dot({ tone }: { tone: string }) {
  return (
    <span
      className={`flex size-3.5 shrink-0 items-center justify-center rounded-full text-white ${tone}`}
    >
      <svg
