                    />
                  ) : (
                    <Check
                      aria-hidden="true"
                      className={cn(
                        "size-3.5 shrink-0",
                        step.state === "done"
                          ? "text-muted-foreground"
                          : "text-border"
                      )}
                    />
                  )}
                  <span
                    className={cn(
                      "min-w-0 truncate text-sm",
                      step.state === "pending"
                        ? "text-muted-foreground"
                        : "font-medium text-foreground"
                    )}
                  >
                    {step.label}
                  </span>
                  {step.detail ? (
                    <span className="shrink-0 font-mono text-xs text-muted-foreground">
                      {step.detail}
                    </span>
                  ) : null}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
