 * usando el endpoint público que devuelve el destino ya validado.
 */
export function PublicLinkBio({ page }: { page: PublicLinkBioPage }) {
  useEffect(() => {
    void linkBioApi.track(page.slug, { type: "view" }).catch(() => {
